const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=v=>Number(v||0).toLocaleString('es-CL',{maximumFractionDigits:1,minimumFractionDigits:1});
const min=s=>{const a=s.split(':').map(Number);return a[0]*60+a[1];};
const sgn=v=>(v>0?'+':'')+num(v);
// Escala redonda (1-2-2,5-5 × 10^n) para que los ejes muestren números limpios.
const niceStep=(max,n=4)=>{const raw=Math.max(max,1e-9)/n,p=10**Math.floor(Math.log10(raw)),f=raw/p;return (f<=1?1:f<=2?2:f<=2.5?2.5:f<=5?5:10)*p;};
const ticks=(max,n=4)=>{const s=niceStep(max,n),top=Math.max(s,Math.ceil(max/s-1e-9)*s);return {s,top,list:Array.from({length:Math.round(top/s)+1},(_,i)=>i*s)};};
const tickTxt=v=>Math.abs(v-Math.round(v))<1e-9?Math.round(v).toLocaleString('es-CL'):v.toLocaleString('es-CL',{maximumFractionDigits:2});
const title=s=>`<title>${esc(s)}</title>`;
const svg=(s,label,w=720,h=280)=>`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(label)}">${s}</svg>`;
export function accumulated(curves,turno,now,projection,{w:W=1300,h:H=245,fs=12}={}){
 // Márgenes, grosores y etiquetas proporcionales a la letra (fs): en una TV grande el texto crece sin cortarse.
 const L=Math.round(fs*3.4+14),R=Math.round(fs*1.2+10),T0=Math.round(fs*1.9+6),B0=H-Math.round(fs*2.1+12),lw=Math.max(2,fs/7),rp=Math.max(4,fs/3);
 const ahoraMin=now.getHours()*60+now.getMinutes(),a=min(turno.inicio),b=min(turno.fin),x=t=>L+(t-a)/(b-a)*(W-L-R),T=ticks(Math.max(1,...curves.flatMap(p=>[p.real,p.teo]),projection.m3RealProy||0,projection.m3TeoProy||0)),max=T.top,y=v=>B0-v/max*(B0-T0);
 const rows=[{h:turno.inicio,real:0,teo:0},...curves.map((p,i)=>{const fin=Math.min(b,min(p.h)+60,i===curves.length-1?Math.max(min(p.h)+1,ahoraMin):1e9);return {...p,h:`${String(Math.floor(fin/60)).padStart(2,'0')}:${String(fin%60).padStart(2,'0')}`};})];
 const grid=T.list.map(v=>`<path class="grid" d="M${L} ${y(v)}H${W-R}"/><text x="${L-7}" y="${y(v)+fs*.35}" text-anchor="end">${tickTxt(v)}</text>`).join('');
 const xc0=x(min(turno.colacion[0])),xc1=x(min(turno.colacion[1]));
 const series=['real','teo'].map((k,i)=>{const color=i?'#129680':'#255de0',last=rows.at(-1),px=x(min(last.h)),py=y(last[k]),pro=i?projection.m3TeoProy:projection.m3RealProy;
  const txt=`${i?'Esperado':'Real'} ${num(last[k])}`,derecha=px+8+fs*.6*txt.length<=W-4;
  return `<polyline style="stroke:${color};stroke-width:${lw};${i?`stroke-dasharray:${lw*4} ${lw*2.5}`:''}" points="${rows.map(p=>`${x(min(p.h))},${y(p[k])}`).join(' ')}"/>${pro!=null?`<path d="M${px} ${py}L${x(b)} ${y(pro)}" fill="none" stroke="${color}" stroke-width="${lw*.75}" stroke-dasharray="${lw} ${lw*2.5}" opacity=".5"/>`:''}<circle cx="${px}" cy="${py}" r="${rp}" fill="${color}"/><text class="halo" x="${derecha?px+8:px-8}" y="${py+(i?-fs*.8:fs*1.35)}" text-anchor="${derecha?'start':'end'}">${txt}</text>`;}).join('');
 const horas=Array.from({length:Math.floor((b-a)/60)+1},(_,i)=>a+i*60).filter(t=>t<=b-20).map(t=>`<text x="${x(t)}" y="${B0+fs*1.55}" text-anchor="middle">${String(Math.floor(t/60)).padStart(2,'0')}:${String(t%60).padStart(2,'0')}</text>`).join('')+`<text x="${x(b)}" y="${B0+fs*1.55}" text-anchor="middle">${turno.fin}</text>`;
 const cursores=rows.map((p,i)=>`<g tabindex="0" data-tip="${esc(p.h+' · Real '+num(p.real)+' m³ · Esperado '+num(p.teo)+' m³'+(p.teoBruto!=null?' · Esperado bruto '+num(p.teoBruto)+' m³':''))}" data-curve="${i}"><rect x="${x(min(p.h))-Math.max(12,fs)}" y="${T0}" width="${Math.max(24,fs*2)}" height="${B0-T0}" fill="transparent"/><path class="curve-cursor" d="M${x(min(p.h))} ${T0}V${B0}" stroke="#333"/>${title(p.h+' · Real '+num(p.real)+' · Esperado '+num(p.teo))}</g>`).join('');
 return svg(grid+`<rect x="${xc0}" y="${T0}" width="${xc1-xc0}" height="${B0-T0}" fill="#888" opacity=".1"/><text x="${xc0}" y="${T0-fs*.45}">Colación</text>`+series+`<path d="M${x(Math.max(a,Math.min(b,ahoraMin)))} ${T0}V${B0}" stroke="#777"/>`+horas+cursores,'Producción acumulada: real vs esperado',W,H);}
export function columns(rows,{reference=0,current='',color='#255de0',label='Trozos por hora'}={}){const T=ticks(Math.max(1,reference,...rows.map(p=>p.value)),3),max=T.top,y=v=>235-v/max*200,step=600/Math.max(1,rows.length);return svg(T.list.map(v=>`<path class="grid" d="M45 ${y(v)}H680"/><text x="38" y="${y(v)+4}" text-anchor="end">${tickTxt(v)}</text>`).join('')+rows.map((p,i)=>{const x=55+i*step,w=Math.min(24,step*.7),v=y(p.value),tip=p.label+' · '+num(p.value);return `<g tabindex="0" data-tip="${esc(tip)}"><path d="M${x} 235V${v+4}Q${x} ${v} ${x+4} ${v}H${x+w-4}Q${x+w} ${v} ${x+w} ${v+4}V235Z" fill="${color}" opacity="${p.label===current?.45:1}"/>${title(tip)}<text x="${x+w/2}" y="255" text-anchor="middle">${esc(p.label)}</text>${p.label===current?`<text x="${x+w/2}" y="${v-8}" text-anchor="middle">en curso</text>`:''}</g>`;}).join('')+(reference?`<path d="M45 ${y(reference)}H680" stroke="#8893a0" stroke-dasharray="6 5"/><text x="680" y="${y(reference)-6}" text-anchor="end" class="halo">Referencia ${Math.round(reference)}/h</text>`:''),label);}
export function horizontal(rows,expected=[]){
 const groups=new Map(rows.map(p=>[p.esc,{...p}]));
 for(const p of expected){const r=groups.get(p.esc)||{esc:p.esc,m3:0,paq:0,piezas:0};r.m3Teo=p.m3Teo;groups.set(p.esc,r);}
 const all=[...groups.values()].sort((a,b)=>(b.m3Teo||0)-(a.m3Teo||0)||b.m3-a.m3),max=Math.max(1,...all.flatMap(p=>[p.m3,p.m3Teo||0]));
 // Real hasta lo esperado en azul; lo que falta en rojo tenue; lo que supera lo esperado en verde. El texto repite el signo (▼/▲).
 const pct=v=>`${Math.max(0,v)/max*100}%`;
 return `<div class="esc-bars">${all.map((p,i)=>{const tiene=p.m3Teo!==undefined,dif=tiene?p.m3-p.m3Teo:0,falta=tiene&&dif<=-.05,sobre=tiene&&dif>=.05,base=tiene?Math.min(p.m3,p.m3Teo):p.m3;
  const barras=`<i class="real${falta||sobre?'':' fin'}" style="width:${pct(base)}"></i>${falta?`<i class="falta" style="left:${pct(p.m3)};width:${pct(-dif)}"></i>`:''}${sobre?`<i class="sobre" style="left:${pct(p.m3Teo)};width:${pct(dif)}"></i>`:''}`;
  const delta=falta?` · <b class="delta falta">▼ faltan ${num(-dif)} m³</b>`:sobre?` · <b class="delta sobre">▲ ${num(dif)} m³ sobre lo esperado</b>`:tiene?' · <b class="delta">= lo esperado</b>':'';
  return `<div class="esc-row" style="--expected:${(p.m3Teo||0)/max*100}%" data-rank="${i}"><b>${esc(p.esc)}</b><span>${barras}${tiene?'<em class="expected-mark"></em>':''}</span><small>${num(p.m3)}${tiene?' de '+num(p.m3Teo)+' m³ esperados':' m³ · sin esperado del modelo'}${delta}<span class="esc-extra"> · ${p.paq.toLocaleString('es-CL')} ${p.paq===1?'paquete':'paquetes'} · ${p.piezas.toLocaleString('es-CL')} piezas</span></small></div>`;}).join('')}</div>`;
}
export function divergent(points){
 // Barras divergentes: escala redonda por lado (no simétrica a la fuerza), extremo redondeado lejos de la línea cero.
 const vals=points.map(p=>p.desvPp*100),pos=Math.max(0,...vals),neg=Math.max(0,...vals.map(v=>-v)),s=niceStep(Math.max(pos,neg,.5),2),top=Math.max(s,Math.ceil(pos/s-1e-9)*s),bot=Math.max(s,Math.ceil(neg/s-1e-9)*s);
 const W=1100,L=60,R=W-20,T0=20,B0=200,y=v=>T0+(top-v)/(top+bot)*(B0-T0),step=(R-L)/Math.max(1,points.length),bw=Math.min(24,step*.6),cada=Math.max(1,Math.ceil(points.length/24));
 const fecha=f=>`${String(f).slice(8,10)}-${String(f).slice(5,7)}`;
 const grid=[];for(let v=-bot;v<=top+1e-9;v+=s)grid.push(`<path class="grid" d="M${L} ${y(v)}H${R}"/><text x="${L-8}" y="${y(v)+4}" text-anchor="end">${tickTxt(v)}</text>`);
 const bars=points.map((p,i)=>{const d=p.desvPp*100,x=L+i*step+(step-bw)/2,y0=y(0),yv=y(d),h=Math.max(1,Math.abs(yv-y0)),r=Math.min(4,h/2,bw/2),tip=`${fecha(p.f)} · ${sgn(d)} puntos (real ${num(p.yieldReal*100)} % · esperado ${num(p.yieldTeo*100)} %)`;
  const path=d>=0?`M${x} ${y0}V${y0-h+r}Q${x} ${y0-h} ${x+r} ${y0-h}H${x+bw-r}Q${x+bw} ${y0-h} ${x+bw} ${y0-h+r}V${y0}Z`:`M${x} ${y0}V${y0+h-r}Q${x} ${y0+h} ${x+r} ${y0+h}H${x+bw-r}Q${x+bw} ${y0+h} ${x+bw} ${y0+h-r}V${y0}Z`;
  return `<g tabindex="0" data-tip="${esc(tip)}"><rect x="${L+i*step}" y="${T0}" width="${step}" height="${B0-T0}" fill="transparent"/><path d="${path}" fill="${d>=0?'#2f6bd8':'#c2413b'}"/>${title(tip)}${i%cada===0||i===points.length-1?`<text x="${x+bw/2}" y="${B0+20}" text-anchor="middle">${esc(fecha(p.f))}</text>`:''}</g>`;}).join('');
 return `<h3 class="chart-title">Diferencia por día: real − esperado (puntos)</h3><div class="chart-legend"><span><i style="background:#2f6bd8"></i>Sobre lo esperado</span><span><i style="background:#c2413b"></i>Bajo lo esperado</span></div>`+svg(grid.join('')+`<path d="M${L} ${y(0)}H${R}" stroke="#8893a0"/>`+bars,'Diferencia real menos esperado por día, en puntos',W,230);
}
export function bindChartTips(root){let tip=root.querySelector('.chart-tip');if(!tip){tip=document.createElement('div');tip.className='chart-tip';tip.setAttribute('role','status');root.append(tip);}root.querySelectorAll('[data-tip]').forEach(el=>{const show=()=>{tip.textContent=el.dataset.tip;tip.hidden=false;const r=el.getBoundingClientRect(),w=tip.offsetWidth,h=tip.offsetHeight;tip.style.left=Math.max(8,Math.min(innerWidth-w-8,r.left+r.width/2-w/2))+'px';tip.style.top=(r.top-h-10>=8?r.top-h-10:r.bottom+10)+'px';};el.onpointerenter=el.onfocus=el.onclick=show;el.onpointerleave=el.onblur=()=>tip.hidden=true;el.onkeydown=e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const list=[...el.ownerSVGElement.querySelectorAll('[data-tip]')],i=list.indexOf(el);list[Math.max(0,Math.min(list.length-1,i+(e.key==='ArrowRight'?1:-1)))].focus();}};});tip.hidden=true;}
